{"function":"() => {
const res=[];
function walk(root){
  for(const el of root.querySelectorAll('*')){
    if(el.shadowRoot) walk(el.shadowRoot);
    const t=el.tabIndex;
    const nat=el.matches('a[href],button,input,select,textarea,[tabindex]');
    if(nat && t>=0 && !el.disabled){
      const r=el.getBoundingClientRect();
      res.push(el.tagName+(el.id?'#'+el.id:'')+' "'+(el.getAttribute('aria-label')??el.textContent.trim().slice(0,25))+'" ti='+el.getAttribute('tabindex')+' '+Math.round(r.x)+','+Math.round(r.y)+' '+Math.round(r.width)+'x'+Math.round(r.height));
    }
  }
}
walk(document);
return res.length+'\n'+res.slice(0,30).join('\n')+'\n...\n'+res.slice(-14).join('\n');
}"}

